glsl:
#version 450
layout(std140, set = 0, binding = 0) uniform NrUniforms { vec3 nr_patch; vec4 c; vec4 nr_unit; }; layout(set = 0, binding = 1) uniform texture2D nr_buffer_nrt; layout(set = 0, binding = 2) uniform sampler nr_buffer_nrs; layout(location = 0) out vec4 nr_FragColor; vec4 nr_FragCoord;




struct Light { vec3 color; float nr_input; };
float nr_filter(Light l) { return l.nr_input + c.b + nr_patch.b; }
void nr_main() {
  Light l = Light(nr_patch, 0.5);
  vec4 t = texture(sampler2D(nr_buffer_nrt, nr_buffer_nrs), nr_FragCoord.xy / 100.0) + textureLod(sampler2D(nr_buffer_nrt, nr_buffer_nrs), vec2(0.5), 0.0);
  nr_FragColor = vec4(l.color * nr_filter(l), 1.0) + t;
}

void main() { nr_FragCoord = vec4(gl_FragCoord.x * nr_unit.x, nr_unit.z - gl_FragCoord.y * nr_unit.y, 0.0, 1.0); nr_FragColor = vec4(0.0); nr_main(); }
